import{_ as a,a as s,c as t,ac as r}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · 综合复习与自测 · 第67–73课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第一册：英语初阶 · 综合复习与自测 · 第67–73课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-1/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第60–66课","link":"/life/english/new-concept/book-1/review-part-09"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第74–80课","link":"/life/english/new-concept/book-1/review-part-11"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第60–66课","link":"/life/english/new-concept/book-1/review-part-09"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第74–80课","link":"/life/english/new-concept/book-1/review-part-11"}},"headers":[],"relativePath":"life/english/new-concept/book-1/review-part-10.md","filePath":"life/english/new-concept/book-1/review-part-10.md"}'),o={name:"life/english/new-concept/book-1/review-part-10.md"};function n(l,e,i,d,h,p){return s(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="第一册-英语初阶-·-综合复习与自测-·-第67–73课" tabindex="-1">第一册：英语初阶 · 综合复习与自测 · 第67–73课 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测-·-第67–73课" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 · 第67–73课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-67-·-be-的过去式-was-were" tabindex="-1">Lesson 67 · be 的过去式 was/were <a class="header-anchor" href="#lesson-67-·-be-的过去式-was-were" aria-label="Permalink to &quot;Lesson 67 · be 的过去式 was/were {#lesson-67-·-be-的过去式-was-were}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I was at the library last Saturday.</p><h3 id="练习-1-66" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-66" aria-label="Permalink to &quot;练习 1 {#练习-1-66}&quot;">​</a></h3><p>填过去式：I ___ at the library last Saturday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> was</p><p><strong>解析：</strong> 按本课规则判断：过去某时的身份、状态或位置可用 was/were。I/he/she/it 用 was，you/we/they 用 were。否定在后面加 not；疑问把 was/were 移到主语前。last weekend、yesterday 指已结束的过去。不要给含 was/were 的问句再加 did；也不要把现在的 are 原样用于过去。</p></details><p><strong>表达迁移：</strong> 围绕“回忆周末在哪里以及当时状态”写两至三句，再读给同伴听。至少使用一次be 的过去式 was/were，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I was at the library last Saturday. Were your friends at the concert yesterday?</p><p>I 配过去式 was；at the library 表位置，last Saturday 明确已结束的过去，前面不加 on。 Were 前置构成过去的 be 问句；your friends 为复数，at the concert 表地点或参与场景。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-067">回看本课</a></p><h2 id="lesson-68-·-be-的过去式-was-were" tabindex="-1">Lesson 68 · be 的过去式 was/were <a class="header-anchor" href="#lesson-68-·-be-的过去式-was-were" aria-label="Permalink to &quot;Lesson 68 · be 的过去式 was/were {#lesson-68-·-be-的过去式-was-were}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Were your friends at the concert yesterday?</p><h3 id="练习-1-67" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-67" aria-label="Permalink to &quot;练习 1 {#练习-1-67}&quot;">​</a></h3><p>填过去式：___ your friends at the concert?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Were</p><p><strong>解析：</strong> 按本课规则判断：过去某时的身份、状态或位置可用 was/were。I/he/she/it 用 was，you/we/they 用 were。否定在后面加 not；疑问把 was/were 移到主语前。last weekend、yesterday 指已结束的过去。不要给含 was/were 的问句再加 did；也不要把现在的 are 原样用于过去。</p></details><p><strong>表达迁移：</strong> 围绕“回忆周末在哪里以及当时状态”写两至三句，再读给同伴听。至少使用一次be 的过去式 was/were，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Were your friends at the concert yesterday? I was at the library last Saturday.</p><p>Were 前置构成过去的 be 问句；your friends 为复数，at the concert 表地点或参与场景。 I 配过去式 was；at the library 表位置，last Saturday 明确已结束的过去，前面不加 on。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-068">回看本课</a></p><h2 id="lesson-69-·-过去存在句与时间介词" tabindex="-1">Lesson 69 · 过去存在句与时间介词 <a class="header-anchor" href="#lesson-69-·-过去存在句与时间介词" aria-label="Permalink to &quot;Lesson 69 · 过去存在句与时间介词 {#lesson-69-·-过去存在句与时间介词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> There were hundreds of people at the race.</p><h3 id="练习-1-68" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-68" aria-label="Permalink to &quot;练习 1 {#练习-1-68}&quot;">​</a></h3><p>填 be 过去式：There ___ hundreds of people.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were</p><p><strong>解析：</strong> 按本课规则判断：there was/there were 介绍过去存在的事物，be 的数取决于后面的名词。There were many people 强调过去人多。on 用具体某天或日期，in 用月份年份等，at 用钟点；含 last、next、every 的时间短语通常不再加介词，如 last Sunday。when 询问时间，不等于 where。</p></details><p><strong>表达迁移：</strong> 围绕“描述过去一场活动的时间与场景”写两至三句，再读给同伴听。至少使用一次过去存在句与时间介词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>There were hundreds of people at the race. The final was on Sunday afternoon.</p><p>There were 引出过去存在的人群；hundreds of people 是复数，at the race 表现场。 The final 是单数主语，用 was；on Sunday afternoon 是具体某天下午，所以使用 on。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-069">回看本课</a></p><h2 id="lesson-70-·-过去存在句与时间介词" tabindex="-1">Lesson 70 · 过去存在句与时间介词 <a class="header-anchor" href="#lesson-70-·-过去存在句与时间介词" aria-label="Permalink to &quot;Lesson 70 · 过去存在句与时间介词 {#lesson-70-·-过去存在句与时间介词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The final was on Sunday afternoon.</p><h3 id="练习-1-69" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-69" aria-label="Permalink to &quot;练习 1 {#练习-1-69}&quot;">​</a></h3><p>补介词：___ Sunday afternoon.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> on</p><p><strong>解析：</strong> 按本课规则判断：there was/there were 介绍过去存在的事物，be 的数取决于后面的名词。There were many people 强调过去人多。on 用具体某天或日期，in 用月份年份等，at 用钟点；含 last、next、every 的时间短语通常不再加介词，如 last Sunday。when 询问时间，不等于 where。</p></details><p><strong>表达迁移：</strong> 围绕“描述过去一场活动的时间与场景”写两至三句，再读给同伴听。至少使用一次过去存在句与时间介词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The final was on Sunday afternoon. There were hundreds of people at the race.</p><p>The final 是单数主语，用 was；on Sunday afternoon 是具体某天下午，所以使用 on。 There were 引出过去存在的人群；hundreds of people 是复数，at the race 表现场。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-070">回看本课</a></p><h2 id="lesson-71-·-一般过去时与-did" tabindex="-1">Lesson 71 · 一般过去时与 did <a class="header-anchor" href="#lesson-71-·-一般过去时与-did" aria-label="Permalink to &quot;Lesson 71 · 一般过去时与 did {#lesson-71-·-一般过去时与-did}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> She called the office twice yesterday.</p><h3 id="练习-1-70" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-70" aria-label="Permalink to &quot;练习 1 {#练习-1-70}&quot;">​</a></h3><p>填过去式：She ___ (call) yesterday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> called</p><p><strong>解析：</strong> 按本课规则判断：规则动词过去式一般加 ed；以 e 结尾加 d，以辅音字母加 y 结尾通常把 y 变 i 加 ed。否定和问句由 did 承担过去标记，后面用原形。I called 与 Did you call? 相互对应，不能写 Did you called?。过去动作是否重复由语境决定，一般过去时也能表达过去的习惯。</p></details><p><strong>表达迁移：</strong> 围绕“回忆过去发生的动作并询问时间”写两至三句，再读给同伴听。至少使用一次一般过去时与 did，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>She called the office twice yesterday. When did you finish the report?</p><p>She called 是一般过去时肯定句；called 为规则过去式，twice 表次数，yesterday 表过去时间。 When 询问完成时间；did 承担过去标记，you 为主语，finish 恢复原形，the report 为宾语。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-071">回看本课</a></p><h2 id="lesson-72-·-一般过去时与-did" tabindex="-1">Lesson 72 · 一般过去时与 did <a class="header-anchor" href="#lesson-72-·-一般过去时与-did" aria-label="Permalink to &quot;Lesson 72 · 一般过去时与 did {#lesson-72-·-一般过去时与-did}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> When did you finish the report?</p><h3 id="练习-1-71" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-71" aria-label="Permalink to &quot;练习 1 {#练习-1-71}&quot;">​</a></h3><p>填原形：When did you ___ (finish)?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> finish</p><p><strong>解析：</strong> 按本课规则判断：规则动词过去式一般加 ed；以 e 结尾加 d，以辅音字母加 y 结尾通常把 y 变 i 加 ed。否定和问句由 did 承担过去标记，后面用原形。I called 与 Did you call? 相互对应，不能写 Did you called?。过去动作是否重复由语境决定，一般过去时也能表达过去的习惯。</p></details><p><strong>表达迁移：</strong> 围绕“回忆过去发生的动作并询问时间”写两至三句，再读给同伴听。至少使用一次一般过去时与 did，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>When did you finish the report? She called the office twice yesterday.</p><p>When 询问完成时间；did 承担过去标记，you 为主语，finish 恢复原形，the report 为宾语。 She called 是一般过去时肯定句；called 为规则过去式，twice 表次数，yesterday 表过去时间。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-072">回看本课</a></p><h2 id="lesson-73-·-不规则过去式" tabindex="-1">Lesson 73 · 不规则过去式 <a class="header-anchor" href="#lesson-73-·-不规则过去式" aria-label="Permalink to &quot;Lesson 73 · 不规则过去式 {#lesson-73-·-不规则过去式}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We took the wrong bus and went to the harbour.</p><h3 id="练习-1-72" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-72" aria-label="Permalink to &quot;练习 1 {#练习-1-72}&quot;">​</a></h3><p>填过去式：We ___ (take) the wrong bus.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> took</p><p><strong>解析：</strong> 按本课规则判断：部分高频动词的过去式不是加 ed：go→went、see→saw、say→said、take→took。肯定句使用过去式，问句和否定句中 did 后恢复原形。复述路线可以按先后顺序组织动作，但 next、then 等顺序词不自动决定时态；应先确认整个故事发生在过去。人名变化不会改变过去式形式。</p></details><p><strong>表达迁移：</strong> 围绕“叙述问路和找到目的地的过程”写两至三句，再读给同伴听。至少使用一次不规则过去式，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We took the wrong bus and went to the harbour. Did the guard show you the right road?</p><p>Took 与 went 是并列的过去时谓语，分别来自 take 和 go；and 连接两个先后相关的动作。 Did 前置询问过去事件，show 恢复原形；you 是接受者，the right road 是被指出的信息。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-073">回看本课</a></p>',60)])])}const w=a(o,[["render",n]]);export{u as __pageData,w as default};
